563:	// This exception follows full entity-schema validation above, and never
564:	// applies to another entity, a foreign project or a non-GLOBAL policy.
565:	projectMatches:=body["project_id"]==project
566:	if project=="" && (kind=="BudgetPolicy" || kind=="RunPolicy") && body["project_id"]==nil && body["scope_type"]=="GLOBAL" && body["scope_id"]=="global" && body["parent_policy_id"]==nil { projectMatches=true }
