568:	if receipt,ok:=body["receipt_hash"];ok {
569:		if receipt!=Receipt(Object(body)) || !f08Equal(receipt,row[5]){return zero,f08Binding}
570:	} else if kind=="Artifact" {
571:		if !f08Equal(body["content_hash"],row[5]){return zero,f08Binding}
572:	} else if row[5]!=nil{return zero,f08Binding}
